import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";

export type User = { id: string; email: string; name: string; passwordHash: string };

const users = new Map<string, User>();

function hashPassword(password: string, salt = randomBytes(16).toString("hex")): string {
  return `${salt}:${scryptSync(password, salt, 32).toString("hex")}`;
}

function checkPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(":");
  const candidate = scryptSync(password, salt, 32);
  return timingSafeEqual(candidate, Buffer.from(hash, "hex"));
}

export class UserError extends Error {}

/** Register a user. Emails are unique (case-insensitive). */
export function createUser(email: string, name: string, password: string): User {
  const normalized = email.trim().toLowerCase();
  if (!/^[^@\s]+@[^@\s]+$/.test(normalized)) throw new UserError("invalid email");
  if (password.length < 8) throw new UserError("password must be at least 8 characters");
  if (findUserByEmail(normalized)) throw new UserError("email already registered");
  const user: User = { id: `u_${randomBytes(6).toString("hex")}`, email: normalized, name: name.trim() || normalized, passwordHash: hashPassword(password) };
  users.set(user.id, user);
  return user;
}

export function findUserByEmail(email: string): User | undefined {
  const normalized = email.trim().toLowerCase();
  for (const u of users.values()) if (u.email === normalized) return u;
  return undefined;
}

export function getUser(id: string): User | undefined {
  return users.get(id);
}

/** The user for an email/password pair, or undefined. */
export function authenticate(email: string, password: string): User | undefined {
  const user = findUserByEmail(email);
  return user && checkPassword(password, user.passwordHash) ? user : undefined;
}

/** Public view of a user (never the password hash). */
export function publicUser(user: User): { id: string; email: string; name: string } {
  return { id: user.id, email: user.email, name: user.name };
}

/** Test helper: forget every user. */
export function resetUsers(): void {
  users.clear();
}
import { authenticate } from "../auth/users.ts";
import { createSession } from "../auth/session.ts";
import { accountRoutes } from "./account.ts";
import { createRouter, field, html, json, type Route } from "./router.ts";
import { loginPage } from "../ui/pages.ts";

/** POST /api/login {email, password} -> {token} */
export function login(email: string, password: string): { token: string } | undefined {
  const user = authenticate(email, password);
  if (!user) return undefined;
  const session = createSession(user.id);
  return { token: session.token };
}

export const routes: Route[] = [
  { method: "GET", path: "/", handler: () => html(200, loginPage()) },
  { method: "GET", path: "/api/health", handler: () => json(200, { ok: true }) },
  {
    method: "POST",
    path: "/api/login",
    handler: (req) => {
      const email = field(req.body, "email");
      const password = field(req.body, "password");
      if (!email || !password) return json(400, { error: "email and password are required" });
      const result = login(email, password);
      return result ? json(200, result) : json(401, { error: "invalid credentials" });
    },
  },
  ...accountRoutes,
];

export const app = createRouter(routes);
import { getUser, publicUser } from "../auth/users.ts";
import { revokeSession } from "../auth/session.ts";
import { field, html, json, sessionOf, type Route } from "./router.ts";
import { accountPage } from "../ui/pages.ts";

export const accountRoutes: Route[] = [
  {
    method: "GET",
    path: "/api/me",
    handler: (req) => {
      const session = sessionOf(req);
      const user = session && getUser(session.userId);
      return user ? json(200, publicUser(user)) : json(401, { error: "not signed in" });
    },
  },
  {
    method: "GET",
    path: "/account",
    handler: (req) => {
      const session = sessionOf(req);
      const user = session && getUser(session.userId);
      return user ? html(200, accountPage(publicUser(user))) : html(401, "<p>Please sign in.</p>");
    },
  },
  {
    method: "POST",
    path: "/api/logout",
    handler: (req) => {
      const session = sessionOf(req);
      if (!session) return json(401, { error: "not signed in" });
      revokeSession(session.token);
      return json(200, { ok: field(req.body, "reason") ?? true });
    },
  },
];
