import { getSession, type Session } from "../auth/session.ts";

export type Request = { method: string; path: string; headers: Record<string, string | undefined>; body?: unknown };
export type Response = { status: number; headers?: Record<string, string>; body: unknown };
export type Handler = (req: Request) => Response | Promise<Response>;
export type Route = { method: string; path: string; handler: Handler };

export const json = (status: number, body: unknown): Response => ({ status, headers: { "content-type": "application/json" }, body });
export const html = (status: number, body: string): Response => ({ status, headers: { "content-type": "text/html; charset=utf-8" }, body });

/** Bearer-token session of a request, or undefined. */
export function sessionOf(req: Request): Session | undefined {
  const auth = req.headers["authorization"] ?? "";
  const m = /^Bearer (\S+)$/.exec(auth);
  return m ? getSession(m[1]) : undefined;
}

/** A string field of a JSON body, or undefined. */
export function field(body: unknown, name: string): string | undefined {
  const v = body && typeof body === "object" ? (body as Record<string, unknown>)[name] : undefined;
  return typeof v === "string" ? v : undefined;
}

export function createRouter(routes: Route[]): Handler {
  return async (req) => {
    const route = routes.find((r) => r.method === req.method && r.path === req.path);
    if (!route) return json(404, { error: "not found" });
    try {
      return await route.handler(req);
    } catch (err) {
      return json(500, { error: err instanceof Error ? err.message : String(err) });
    }
  };
}
import { randomBytes } from "node:crypto";

export type Session = { token: string; userId: string; createdAt: number };

const sessions = new Map<string, Session>();

/** Start a session for a user and return it (the token is the bearer credential). */
export function createSession(userId: string): Session {
  const session: Session = { token: randomBytes(24).toString("base64url"), userId, createdAt: Date.now() };
  sessions.set(session.token, session);
  return session;
}

/** The live session for a token, or undefined. */
export function getSession(token: string): Session | undefined {
  return sessions.get(token);
}

export function revokeSession(token: string): boolean {
  return sessions.delete(token);
}

/** Test helper: forget every session. */
export function resetSessions(): void {
  sessions.clear();
}
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { createUser, resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
  createUser("ada@example.com", "Ada", "correct horse");
});

test("login with valid credentials returns a token that works for /api/me", async () => {
  const res = await call("POST", "/api/login", { email: "ADA@example.com", password: "correct horse" });
  assert.equal(res.status, 200);
  const { token } = res.body as { token: string };
  const me = await call("GET", "/api/me", undefined, token);
  assert.deepEqual(me.body, { id: (me.body as { id: string }).id, email: "ada@example.com", name: "Ada" });
});

test("login rejects a wrong password and missing fields", async () => {
  assert.equal((await call("POST", "/api/login", { email: "ada@example.com", password: "nope nope" })).status, 401);
  assert.equal((await call("POST", "/api/login", { email: "ada@example.com" })).status, 400);
});

test("logout revokes the token", async () => {
  const { token } = (await call("POST", "/api/login", { email: "ada@example.com", password: "correct horse" })).body as { token: string };
  assert.equal((await call("POST", "/api/logout", {}, token)).status, 200);
  assert.equal((await call("GET", "/api/me", undefined, token)).status, 401);
});

test("pages render and unknown routes 404", async () => {
  const home = await call("GET", "/");
  assert.match(String(home.body), /<h1>Sign in<\/h1>/);
  assert.equal((await call("GET", "/nope")).status, 404);
});

