  await call("POST", "/api/signup", { email: "grace@example.com", name: "Grace", password: "hopper1906" });
  const dup = await call("POST", "/api/signup", { email: "GRACE@example.com", name: "G", password: "hopper1906" });
  assert.deepEqual(dup, { status: 400, headers: { "content-type": "application/json" }, body: { error: "email already registered" } });
  assert.equal((await call("POST", "/api/signup", { email: "nope", name: "X", password: "hopper1906" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { email: "a@b.c", name: "X", password: "short" })).status, 400);
  assert.equal((await call("POST", "/api/signup", {})).status, 400);
});
